    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int math, lit;
    int total() const { return math + lit; }
};

int main() {
    int n;
    if (cin >> n) {
        string bestName = "";
        int bestTotal = -1;
        for (int i = 0; i < n; i++) {
            Student s;
            cin >> s.name >> s.math >> s.lit;
            if (s.total() > bestTotal) {
                bestTotal = s.total();
                bestName = s.name;
            }
        }
        cout << bestName << " " << bestTotal << "\n";
    }
    return 0;
}

